      id: "agree_help_joss",
      label: "Offer to find Joss a new millstone",
      params: {},
      requires: ["at(pov, 'wend_mill')", "at('joss_tamber', here)"],
      outcomes: {
        default: [
          { type: "story.flag", args: { name: "joss_helping", value: true } },
          {
            type: "note",
            args: { text: "Joss says a runner stone needs to be about this wide and this thick, and that the old quarry on the Hollin road once cut them." }
          }
        ]
      },
      duration: "15",
      lexicon: ["help joss", "find a millstone", "offer to help the miller"],
      observable: "talks with Joss"
