// src/packs/starters/index.ts
var starter = (doc) => (id, name) => ({ ...structuredClone(doc), id, name });
var STARTER_WORLDS = {
  fantasy_town: starter(fantasy_town_default),
  mystery_manor: starter(mystery_manor_default),
  modern_slice_of_life: starter(modern_slice_of_life_default)
};

// src/packs/index.ts
var ALL_PACKS = [enginePack, core_default, core_default2, core_default3, core_default4, core_default5, core_default6, core_default7, core_default8, core_default9, core_default10];

// src/worker/background-lane.ts
var CHECK_MAX_DAYS = 14;
function run(proc) {
  proc.ready();
  let stopped = false;
  proc.onStop(() => {
    stopped = true;
    proc.complete();
  });
  const p = proc.payload;
  if (!isRecord(p) || typeof p.jobId !== "string" || !isWorldDoc(p.world) || typeof p.revision !== "string") {
    proc.fail("bad lane payload");
    return;
  }
  const jobId = p.jobId;
  const world = p.world;
  const runSeed = typeof p.runSeed === "string" ? p.runSeed : jobId;
  const registry = createRegistry(ALL_PACKS);
  const pipeline = { plan: planTurn, post: postTurn };
  let step;
  let count;
  if (p.kind === "check_world") {
    const overrides = {};
    for (const id of Object.keys(world.time.interrupts))
      overrides[id] = "note";
    const intent = timelapseIntent({ type: "duration", minutes: 24 * 60 }, overrides);
    count = Math.max(1, Math.min(CHECK_MAX_DAYS, typeof p.days === "number" ? Math.floor(p.days) : 3));
    step = (state, i) => checkWorldDay(registry, pipeline, world, state, runSeed, i, intent);
  } else {
    const turns = Array.isArray(p.turns) ? p.turns.filter((t) => typeof t === "string") : [];
    count = turns.length;
    step = (state, i) => playtestTurn(registry, pipeline, world, state, turns[i] ?? "", runSeed, i);
  }
  let state = playtestStart(world, p.revision);
  const out = [];
  const next = (i) => {
    if (stopped)
      return;
    if (i >= count) {
      proc.send({ jobId, done: true, result: { turns: out, lint: lintWorld(world, registry) } });
      proc.complete();
      return;
    }
    try {
      const result = step(state, i);
      state = result.state;
      out.push(result.turn);
      proc.heartbeat();
      proc.send({ jobId, progress: (i + 1) / count });
      setTimeout(() => next(i + 1), 0);
    } catch (error) {
      proc.send({ jobId, error: error instanceof Error ? error.message : String(error) });
      proc.fail(error instanceof Error ? error.message : String(error));
    }
  };
  next(0);
}
export {
  CHECK_MAX_DAYS,
  run as default
};
